{"implementation":"def solve(case):
    """Filter Toolformer-style API call candidates by normalized loss improvement."""

    def require_mapping(value, name):
        if not isinstance(value, dict):
            raise ValueError(name + " must be an object")
        return value

    def require_number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(name + " must be a number")
        if value != value or value in (float("inf"), float("-inf")):
            raise ValueError(name + " must be finite")
        return float(value)

    def require_nonnegative_int(value, name):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(name + " must be an integer")
        if value < 0:
            raise ValueError(name + " must be nonnegative")
        return value

    def rounded(value):
        return round(float(value), 6)

    root = require_mapping(case, "case")
    payload = root.get("payload", root)
    payload = require_mapping(payload, "payload")

    if "threshold" not in payload:
        raise ValueError("payload.threshold is required")
    if "calls" not in payload:
        raise ValueError("payload.calls is required")

    threshold = require_number(payload["threshold"], "payload.threshold")
    calls = payload["calls"]
    if not isinstance(calls, list):
        raise ValueError("payload.calls must be a list")

    diagnostics = []
    accepted_call_ids = []

    for position, raw_call in enumerate(calls):
        call = require_mapping(raw_call, "payload.calls[%d]" % position)
        for field in ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable"):
            if field not in call:
                raise ValueError("payload.calls[%d].%s is required" % (position, field))

        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id:
            raise ValueError("payload.calls[%d].call_id must be a nonempty string" % position)

        loss_without = require_number(call["loss_without_call"], "payload.calls[%d].loss_without_call" % position)
        loss_with = require_number(call["loss_with_call"], "payload.calls[%d].loss_with_call" % position)
        prediction_tokens = require_nonnegative_int(call["prediction_tokens"], "payload.calls[%d].prediction_tokens" % position)
        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError("payload.calls[%d].parseable must be a boolean" % position)

        normalizer = max(1, prediction_tokens)
        loss_gain = loss_without - loss_with
        normalized_gain = loss_gain / normalizer
        accepted = bool(parseable and normalized_gain >= threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            "call_id": call_id,
            "source_position": position,
            "parseable": parseable,
            "prediction_tokens": prediction_tokens,
            "normalizer": normalizer,
            "loss_without_call": rounded(loss_without),
            "loss_with_call": rounded(loss_with),
            "loss_gain": rounded(loss_gain),
            "normalized_gain": rounded(normalized_gain),
            "threshold": rounded(threshold),
            "accepted": accepted,
        })

    accepted_count = sum(1 for item in diagnostics if item["accepted"])
    rejected_count = len(diagnostics) - accepted_count

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
        "accepted_count": accepted_count,
        "rejected_count": rejected_count,
        "total_calls": len(diagnostics),
    }
"}
